// WebSocket connect with backoff
let ws, retry = 1;
function connect() {
  ws = new WebSocket('ws://example/ws');
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data);
    if (!isDuplicate(m.id)) appendItem(m);
  };
  ws.onclose = () => {
    setTimeout(connect, Math.min(30000, 1000 * retry));
    retry = Math.min(30, retry + 1);
